<?php get_header(); ?><main id="content" class="site-content rp-container"><?php while(have_posts()):the_post();?><div class="single-layout<?php echo get_theme_mod('rss_prism_show_sidebar',true)&&is_active_sidebar('sidebar-1')?'':' single-layout--no-sidebar'; ?>"><article <?php post_class('entry-card'); ?> id="post-<?php the_ID(); ?>"><h1 class="entry-title"><?php the_title(); ?></h1><?php rss_prism_meta();if(has_post_thumbnail()):?><div class="single-featured-image"><?php the_post_thumbnail('full'); ?></div><?php endif;?><div class="entry-content"><?php the_content();wp_link_pages();?></div><div class="entry-meta"><?php the_category(', ');the_tags(' · '); ?></div><?php the_post_navigation(array('prev_text'=>'<span>'.esc_html__('Previous','rss-prism').'</span><br>%title','next_text'=>'<span>'.esc_html__('Next','rss-prism').'</span><br>%title'));if(comments_open()||get_comments_number())comments_template();?></article><?php rss_prism_sidebar();?></div><?php endwhile;?></main><?php get_footer(); ?>